def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for tile_r in range(3):
        for r in range(h):
            src_r = h - 1 - r if tile_r % 2 == 0 else r
            row = []
            for tile_c in range(2):
                src = grid[src_r]
                row.extend(src[::-1] if tile_c == 0 else src)
            out.append(row)
    return out
